static irqreturn_t arc_serial_isr ( int irq , void * dev_id ) { struct uart_port * port = dev_id ; int status ; status = UART_GET_STATUS ( port ) ; if ( status & RXIENB ) { spin_lock ( & port -> lock ) ; arc_serial_rx_chars ( port , status ) ; spin_unlock ( & port -> lock ) ; } if ( ( status & TXIENB ) && ( status & TXEMPTY ) ) { UART_TX_IRQ_DISABLE ( port ) ; spin_lock ( & port -> lock ) ; if ( ! uart_tx_stopped ( port ) ) { arc_serial_tx_chars ( port ) ; } spin_unlock ( & port -> lock ) ; } return IRQ_HANDLED ; } 